shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #ebe5d8;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c9c1b0;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.13);
    --navy-bg: #0f1d2b;
    --navy-card: #16283b;
    --navy-line: #294057;
    --navy-text: #f0ede6;
    --navy-muted: #9eb0c2;
    --crimson: #9e2a2b;
    --forest: #2b593f;
    --font-serif-cn: 'Noto Serif SC', 'Songti SC', serif;
    --font-sans-cn: 'Noto Sans SC', 'PingFang SC', sans-serif;
    --font-serif-en: 'Lora', Georgia, serif;
    --font-display-en: 'Playfair Display', Georgia, serif;
    --font-sans-en: 'Inter', -apple-system, sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
  }

  *, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    scroll-behavior: smooth;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    overflow-x: hidden;
  }

  .wsj-shadow-body {
    background-color: var(--paper);
    color: var(--body);
    font-family: var(--font-serif-cn);
    line-height: 1.85;
    overflow-x: hidden;
    width: 100%;
  }

  :host([lang="en"]) .wsj-shadow-body {
    font-family: var(--font-serif-en);
    line-height: 1.78;
  }

  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  /* Reading Progress Bar */
  .progress-bar-wrap {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 3px;
    background: rgba(20, 20, 19, 0.06);
    z-index: 1001;
  }
  .progress-bar-fill {
    height: 100%;
    width: 0%;
    background: var(--accent);
    transition: width 0.1s ease-out;
  }

  /* Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 1000;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--line);
    padding: 0 24px;
    height: 58px;
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  .masthead-brand {
    display: flex;
    align-items: center;
    gap: 12px;
  }

  .wsj-monogram {
    font-family: var(--font-display-en);
    font-weight: 800;
    font-size: 1.15rem;
    letter-spacing: 0.06em;
    color: var(--ink);
    border-right: 1px solid var(--line-strong);
    padding-right: 12px;
  }

  .series-tag {
    font-family: var(--font-sans-cn);
    font-size: 0.78rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
  }
  :host([lang="en"]) .series-tag {
    font-family: var(--font-sans-en);
  }

  .masthead-controls {
    display: flex;
    align-items: center;
    gap: 16px;
  }

  .chapter-nav {
    display: flex;
    gap: 18px;
    font-family: var(--font-sans-cn);
    font-size: 0.76rem;
    color: var(--muted);
  }
  :host([lang="en"]) .chapter-nav {
    font-family: var(--font-sans-en);
  }
  .chapter-nav a {
    color: var(--muted);
    text-decoration: none;
    transition: color 0.2s;
  }
  .chapter-nav a:hover {
    color: var(--ink);
  }

  .lang-switch {
    display: inline-flex;
    background: var(--paper-deep);
    border: 1px solid var(--line-strong);
    border-radius: 4px;
    padding: 2px;
  }

  .lang-btn {
    border: none;
    background: transparent;
    padding: 4px 10px;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 700;
    color: var(--muted);
    cursor: pointer;
    border-radius: 2px;
    transition: all 0.18s ease;
  }

  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  /* Container System */
  .page-shell {
    max-width: 1260px;
    margin: 0 auto;
    padding: 0 32px;
  }

  /* Hero Header */
  .article-hero {
    padding: 56px 0 40px;
    border-bottom: 1px solid var(--ink);
    position: relative;
  }

  .hero-kicker-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 12px;
    margin-bottom: 20px;
  }

  .kicker-pill {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    font-family: var(--font-mono);
    font-size: 0.76rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--accent);
    background: var(--accent-soft);
    padding: 5px 12px;
    border-left: 3px solid var(--accent);
  }

  .issue-meta {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    color: var(--muted);
  }

  .hero-headline {
    font-family: var(--font-serif-cn);
    font-weight: 700;
    font-size: clamp(2.1rem, 4.3vw, 3.6rem);
    line-height: 1.22;
    color: var(--ink);
    letter-spacing: -0.015em;
    max-width: 980px;
    margin-bottom: 18px;
  }
  :host([lang="en"]) .hero-headline {
    font-family: var(--font-display-en);
    font-weight: 800;
    line-height: 1.1;
    letter-spacing: -0.02em;
  }

  .hero-dek {
    font-family: var(--font-sans-cn);
    font-weight: 400;
    font-size: clamp(1.1rem, 1.8vw, 1.38rem);
    line-height: 1.6;
    color: var(--muted);
    max-width: 820px;
    margin-bottom: 32px;
  }
  :host([lang="en"]) .hero-dek {
    font-family: var(--font-serif-en);
    font-style: italic;
    line-height: 1.5;
  }

  .hero-byline-bar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    padding-top: 20px;
    border-top: 1px solid var(--line);
    font-family: var(--font-sans-cn);
    font-size: 0.85rem;
    color: var(--muted);
  }
  :host([lang="en"]) .hero-byline-bar {
    font-family: var(--font-sans-en);
  }

  .byline-author strong {
    color: var(--ink);
    font-weight: 700;
  }

  /* Executive Context Dossier + Top Metrics Strip */
  .dossier-grid {
    display: grid;
    grid-template-columns: 1.25fr 1fr;
    gap: 28px;
    margin: 36px 0 52px;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 28px;
  }

  .dossier-box-header {
    display: flex;
    align-items: center;
    gap: 10px;
    font-family: var(--font-mono);
    font-size: 0.74rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    color: var(--accent);
    margin-bottom: 12px;
  }

  .dossier-prose {
    font-size: 0.96rem;
    line-height: 1.78;
    color: var(--body);
  }

  .dossier-metrics {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 14px;
    border-left: 1px solid var(--line-strong);
    padding-left: 24px;
  }

  .mini-stat {
    background: var(--paper);
    border: 1px solid var(--line);
    padding: 12px 14px;
  }

  .mini-stat .metric-val {
    font-family: var(--font-mono);
    font-size: 1.35rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.2;
    margin-bottom: 4px;
  }
  .mini-stat.accent-stat .metric-val {
    color: var(--accent);
  }

  .mini-stat .metric-lbl {
    font-family: var(--font-sans-cn);
    font-size: 0.76rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.35;
  }
  :host([lang="en"]) .mini-stat .metric-lbl {
    font-family: var(--font-sans-en);
  }

  .mini-stat .metric-note {
    font-family: var(--font-sans-cn);
    font-size: 0.7rem;
    color: var(--muted);
    line-height: 1.35;
    margin-top: 3px;
  }
  :host([lang="en"]) .mini-stat .metric-note {
    font-family: var(--font-sans-en);
  }

  /* Editorial Two-Column Asymmetric Layout */
  .editorial-section {
    display: grid;
    grid-template-columns: minmax(0, 680px) minmax(280px, 420px);
    justify-content: space-between;
    gap: 56px;
    margin-bottom: 64px;
    position: relative;
  }

  .narrative-col {
    width: 100%;
  }

  .forensic-rail {
    width: 100%;
    display: flex;
    flex-direction: column;
    gap: 28px;
  }

  .rail-sticky {
    position: sticky;
    top: 84px;
    display: flex;
    flex-direction: column;
    gap: 24px;
  }

  /* Chapter Headers */
  .chapter-banner {
    margin: 12px 0 28px;
    padding-bottom: 14px;
    border-bottom: 2px solid var(--ink);
  }

  .chapter-num {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    display: block;
    margin-bottom: 6px;
  }

  .chapter-title {
    font-family: var(--font-serif-cn);
    font-size: 1.55rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.3;
  }
  :host([lang="en"]) .chapter-title {
    font-family: var(--font-display-en);
    font-size: 1.65rem;
  }

  /* Prose Styling — Strictly Respecting Chinese Typography Discipline */
  .prose-p {
    font-size: 1.125rem;
    line-height: 1.9;
    color: var(--body);
    margin-bottom: 1.55rem;
    text-align: left;
  }

  :host([lang="en"]) .prose-p {
    font-size: 1.1rem;
    line-height: 1.82;
  }

  /* Lead paragraph stature (No ::first-letter drop-cap on Chinese) */
  .lead-paragraph {
    font-size: 1.28rem;
    line-height: 1.85;
    font-weight: 600;
    color: var(--ink);
    border-left: 3px solid var(--accent);
    padding-left: 20px;
    margin-bottom: 1.8rem;
  }
  :host([lang="en"]) .lead-paragraph {
    font-size: 1.24rem;
    line-height: 1.75;
  }

  /* Inline Highlight Mark */
  mark.ed-hl {
    background: linear-gradient(180deg, transparent 58%, rgba(184, 93, 25, 0.22) 58%);
    color: inherit;
    padding: 0 2px;
    font-weight: 600;
  }

  /* Pull Quotes */
  .pull-quote {
    background: var(--paper-card);
    border-top: 3px solid var(--accent);
    border-bottom: 1px solid var(--line-strong);
    padding: 24px 22px;
    margin: 8px 0;
  }

  .pull-quote .quote-text {
    font-family: var(--font-serif-cn);
    font-size: 1.08rem;
    font-weight: 600;
    line-height: 1.68;
    color: var(--ink);
    margin-bottom: 12px;
  }
  :host([lang="en"]) .pull-quote .quote-text {
    font-family: var(--font-display-en);
    font-style: italic;
    font-weight: 700;
  }

  .pull-quote .quote-attrib {
    font-family: var(--font-sans-cn);
    font-size: 0.78rem;
    color: var(--muted);
    line-height: 1.45;
  }
  :host([lang="en"]) .pull-quote .quote-attrib {
    font-family: var(--font-sans-en);
  }

  /* Forensic Exhibit Cards */
  .exhibit-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 22px;
  }

  .exhibit-kicker {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--accent);
    margin-bottom: 6px;
  }

  .exhibit-title {
    font-family: var(--font-sans-cn);
    font-size: 1.02rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 6px;
    line-height: 1.38;
  }
  :host([lang="en"]) .exhibit-title {
    font-family: var(--font-sans-en);
  }

  .exhibit-sub {
    font-family: var(--font-sans-cn);
    font-size: 0.8rem;
    color: var(--muted);
    margin-bottom: 16px;
    line-height: 1.5;
  }
  :host([lang="en"]) .exhibit-sub {
    font-family: var(--font-sans-en);
  }

  .svg-wrap {
    width: 100%;
    overflow: hidden;
  }

  .svg-wrap svg {
    width: 100%;
    height: auto;
    display: block;
  }

  /* Full-Bleed Analytical Break: The Yield Gap & Participation Ratchet */
  .analytical-break {
    background: var(--navy-bg);
    color: var(--navy-text);
    padding: 56px 0;
    margin: 24px 0 64px;
    border-top: 4px solid var(--accent);
    border-bottom: 4px solid var(--accent);
  }

  .break-header {
    margin-bottom: 36px;
    max-width: 820px;
  }

  .break-kicker {
    font-family: var(--font-mono);
    font-size: 0.76rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #f2994a;
    margin-bottom: 8px;
  }

  .break-title {
    font-family: var(--font-serif-cn);
    font-size: clamp(1.5rem, 2.5vw, 2.15rem);
    font-weight: 700;
    color: #ffffff;
    line-height: 1.3;
    margin-bottom: 10px;
  }
  :host([lang="en"]) .break-title {
    font-family: var(--font-display-en);
  }

  .break-desc {
    font-family: var(--font-sans-cn);
    font-size: 0.94rem;
    color: var(--navy-muted);
    line-height: 1.65;
  }
  :host([lang="en"]) .break-desc {
    font-family: var(--font-sans-en);
  }

  .break-charts-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 32px;
    margin-bottom: 32px;
  }

  .navy-panel {
    background: var(--navy-card);
    border: 1px solid var(--navy-line);
    padding: 24px;
  }

  .navy-panel-title {
    font-family: var(--font-sans-cn);
    font-size: 0.96rem;
    font-weight: 700;
    color: #ffffff;
    margin-bottom: 6px;
  }
  :host([lang="en"]) .navy-panel-title {
    font-family: var(--font-sans-en);
  }

  .navy-panel-sub {
    font-family: var(--font-sans-cn);
    font-size: 0.78rem;
    color: var(--navy-muted);
    margin-bottom: 18px;
    line-height: 1.45;
  }
  :host([lang="en"]) .navy-panel-sub {
    font-family: var(--font-sans-en);
  }

  .break-metrics-strip {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
  }

  .navy-metric {
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid var(--navy-line);
    padding: 16px;
  }

  .navy-metric .metric-val {
    font-family: var(--font-mono);
    font-size: 1.45rem;
    font-weight: 700;
    color: #f2994a;
    margin-bottom: 4px;
  }

  .navy-metric .metric-lbl {
    font-family: var(--font-sans-cn);
    font-size: 0.8rem;
    font-weight: 700;
    color: #ffffff;
    margin-bottom: 4px;
  }
  :host([lang="en"]) .navy-metric .metric-lbl {
    font-family: var(--font-sans-en);
  }

  .navy-metric .metric-note {
    font-family: var(--font-sans-cn);
    font-size: 0.72rem;
    color: var(--navy-muted);
    line-height: 1.4;
  }
  :host([lang="en"]) .navy-metric .metric-note {
    font-family: var(--font-sans-en);
  }

  /* Corporate Defense Dossier Card */
  .defense-dossier {
    background: var(--paper-card);
    border-left: 4px solid var(--ink);
    padding: 20px 22px;
    margin: 22px 0 28px;
  }

  .defense-tag {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--ink);
    margin-bottom: 10px;
  }

  /* Climactic Verdict Box */
  .verdict-box {
    background: var(--ink);
    color: var(--paper);
    padding: 36px 32px;
    margin-top: 28px;
    border-left: 6px solid var(--accent);
    position: relative;
  }

  .verdict-kicker {
    font-family: var(--font-mono);
    font-size: 0.76rem;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: #f2994a;
    margin-bottom: 14px;
  }

  .verdict-quote {
    font-family: var(--font-serif-cn);
    font-size: clamp(1.3rem, 2.2vw, 1.7rem);
    font-weight: 700;
    line-height: 1.5;
    color: #ffffff;
    margin-bottom: 16px;
  }
  :host([lang="en"]) .verdict-quote {
    font-family: var(--font-display-en);
    font-style: italic;
    line-height: 1.38;
  }

  .verdict-footer {
    font-family: var(--font-sans-cn);
    font-size: 0.84rem;
    color: #bfb9ad;
  }
  :host([lang="en"]) .verdict-footer {
    font-family: var(--font-sans-en);
  }

  /* Footer */
  .article-footer {
    border-top: 1px solid var(--line-strong);
    padding: 40px 0 64px;
    margin-top: 64px;
    font-family: var(--font-sans-cn);
    font-size: 0.8rem;
    color: var(--muted);
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 16px;
  }
  :host([lang="en"]) .article-footer {
    font-family: var(--font-sans-en);
  }

  /* Responsive Breakpoints (1440px Desktop down to 390px Mobile) */
  @media (max-width: 1024px) {
    .dossier-grid {
      grid-template-columns: 1fr;
    }
    .dossier-metrics {
      border-left: none;
      border-top: 1px solid var(--line-strong);
      padding-left: 0;
      padding-top: 20px;
    }
    .editorial-section {
      grid-template-columns: 1fr;
      gap: 36px;
    }
    .rail-sticky {
      position: static;
    }
    .break-charts-grid {
      grid-template-columns: 1fr;
    }
    .break-metrics-strip {
      grid-template-columns: repeat(2, 1fr);
    }
    .chapter-nav {
      display: none;
    }
  }

  @media (max-width: 600px) {
    .page-shell {
      padding: 0 18px;
    }
    .masthead {
      padding: 0 16px;
      height: 52px;
    }
    .wsj-monogram {
      font-size: 1rem;
      padding-right: 8px;
    }
    .series-tag {
      font-size: 0.7rem;
    }
    .article-hero {
      padding: 32px 0 28px;
    }
    .hero-headline {
      font-size: 1.85rem;
    }
    .hero-dek {
      font-size: 1.02rem;
    }
    .dossier-grid {
      padding: 18px;
      margin: 24px 0 36px;
    }
    .dossier-metrics {
      grid-template-columns: 1fr;
    }
    .prose-p {
      font-size: 1.05rem;
      line-height: 1.82;
    }
    .lead-paragraph {
      font-size: 1.12rem;
      padding-left: 14px;
    }
    .break-metrics-strip {
      grid-template-columns: 1fr;
    }
    .navy-panel, .exhibit-card {
      padding: 16px;
    }
    .verdict-box {
      padding: 24px 20px;
    }
  }
